const metricas = $input.first().json;

const mesAnterior = new Date();
mesAnterior.setMonth(mesAnterior.getMonth() - 1);
const nombreMes = mesAnterior.toLocaleString('es-PE', { month: 'long', year: 'numeric' });

return [{
  json: {
    mes: nombreMes,
    metricas,
    resumenParaPrompt: JSON.stringify(metricas, null, 2),
  },
}];

