// La API de Anthropic (Messages) devuelve el texto en content[0].text.
const respuesta = $input.first().json;
const narrativa =
  (respuesta && respuesta.content && respuesta.content[0] && respuesta.content[0].text) ||
  '(no se pudo generar la narrativa: la respuesta de Claude no trajo contenido de texto)';

const contexto = $('Formatear metricas para el prompt').item.json;

return [{
  json: {
    mes: contexto.mes,
    metricas: contexto.metricas,
    narrativa,
    estado: 'listo_para_envio',
    generadoEn: new Date().toISOString(),
  },
}];
// NOTA (ver README): la especificacion (seccion 11) describe este flujo como
// "narrativa -> PDF -> envio". Este nodo se detiene en "narrativa lista":
// no genera PDF (ningun nodo de la lista de nodos estandar autorizada para
// esta rama lo hace) ni lo envia (no hay canal de envio ni credencial
// definidos para el reporte mensual en config.ts ni en la especificacion).
// Se documenta como contradiccion/vacio en el informe final, no se inventa
// un canal de entrega que nadie pidio.

